function icon(k,p,x,y,s,col,sw){const n=N[k].createInstance();p.appendChild(n);try{n.resize(s,s)}catch(e){}n.x=x;n.y=y;strokesOf(n).forEach(c=>{try{c.strokes=S(col);if(sw)c.strokeWeight=sw}catch(e){}});return n}
function tx(p,name,x,y,w,chars,o={}){const t=figma.createText();p.appendChild(t);t.name=name;t.fontName={family:'Nunito',style:o.w||'Medium'};t.fontSize=o.s||10;t.characters=chars;t.fills=S(o.c||C.cap);t.lineHeight={unit:'AUTO'};t.textAlignHorizontal=o.align||'RIGHT';t.textAutoResize='HEIGHT';t.resize(w,10);t.x=x;t.y=y;return t}
