const H=h=>{h=h.replace('#','');return{r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255}};
function fix(name,x,y,w,txt){
  const t=SC.findOne(n=>n.name===name);
  if(!t) return 'missing';
  t.textAutoResize='WIDTH_AND_HEIGHT';
  t.textAlignHorizontal='RIGHT';
  t.characters=txt;
  t.resize(w,12);
  // right-align inside a fixed box
  t.x=x; t.y=y;
  return {x:t.x,w:Math.round(t.width),h:Math.round(t.height)};
}
